(()=>{var c={header:document.querySelector("header"),hero:document.querySelector("header .hero"),mainContainer:document.querySelector("main .container")};var r=()=>{let e=document.getElementById("view-profile"),o=document.getElementById("profile");if(!e||!o)return;let t=e.classList.toggle("active");if(o.classList.toggle("d-none",t),e.classList.toggle("d-none",!t),t)window.scrollTo({top:0});else{let n=document.querySelector("header .header-top")?.offsetHeight||0;o.scrollIntoView({block:"start"}),window.scrollTo({top:window.scrollY-n-10})}},l=document.querySelectorAll(".toggle-profile");l.forEach(e=>{e.addEventListener("click",o=>{o.preventDefault(),r()})});})();
